(function(){AppModule.register({routes:[
{path:"creation/brief",title:"创意与剧本",permission:"creation.write",render(){return UI.head("创意与剧本","先定义创作目标，再生成故事方案和剧本；不依赖智能体编排。",UI.btn("生成创意方案","generate","primary"))+'<div class="grid grid-2">'+UI.card("创意输入方式",'<div class="list"><div class="list-row"><div><b>自由描述</b><div class="small muted">用自然语言描述灵感、人物、冲突或场景。</div></div><span class="pill blue">推荐</span></div><div class="list-row"><div><b>题材与类型选择</b><div class="small muted">选择题材、类型、受众和风格约束。</div></div></div><div class="list-row"><div><b>故事梗概扩写</b><div class="small muted">将已有梗概扩展为主线和分集结构。</div></div></div><div class="list-row"><div><b>角色关系驱动</b><div class="small muted">从人物目标、关系和核心矛盾出发。</div></div></div><div class="list-row"><div><b>场景 / 事件驱动</b><div class="small muted">从一个场景、事件或反转设想展开。</div></div></div><div class="list-row"><div><b>参考资料辅助</b><div class="small muted">仅分析有权使用的资料并保留来源。</div></div></div></div>')+UI.card("创作需求",'<div class="field"><label>项目</label><select><option>雾城来信 · SP-26031</option><option>新建项目后选择</option></select></div><div class="field"><label>创意描述</label><textarea placeholder="描述故事灵感、核心冲突、人物关系、希望观众获得的情绪体验…"></textarea></div><div class="form-grid">'+UI.select("目标受众","audience",["18–30 岁","25–40 岁","全年龄"])+UI.select("题材","genre",["都市悬疑","都市情感","古装传奇","奇幻"])+UI.select("计划集数","episodes",["12","16","20","24","30"])+UI.select("视觉风格","style",["电影写实","都市质感","漫画风格","年代影像"])+'</div><div class="head-actions">'+UI.btn("保存创意需求","noop")+' '+UI.btn("生成故事方案","generate","primary")+'</div>')+'</div><div class="notice" style="margin-top:16px">生成按钮仅演示交互，不调用真实模型。真实流程须记录输入版本、个人模型配置、调用回执、输出校验和费用。</div>';}},
{path:"creation/script-review",title:"剧本审核",permission:"creation.write",render(){return UI.head("剧本审核","正式剧本版本是后续导演规划和生产任务的唯一基准。")+ '<div class="grid grid-2">'+UI.card("剧本版本 · V3",'<div class="list"><div class="list-row"><span>项目</span><b>雾城来信</b></div><div class="list-row"><span>集数</span><b>24 集</b></div><div class="list-row"><span>场次</span><b>86 场</b></div><div class="list-row"><span>字数</span><b>约 28,600</b></div><div class="list-row"><span>状态</span>'+UI.tag("待审核")+'</div></div><div class="notice" style="margin-top:12px">请重点核对人物动机、主线逻辑、分集节奏、集尾钩子和版权/合规提示。</div><div class="head-actions" style="margin-top:14px">'+UI.btn("退回修改","return-script")+' '+UI.btn("审核通过并锁定","approve-script","primary")+'</div>')+UI.card("剧本审核清单",'<div class="list">'+["故事方向符合项目目标","人物设定和关系清晰","分集剧情逻辑连续","对白与场景适配","单集节奏和集尾钩子明确","内容合规与授权风险已检查"].map(x=>'<div class="list-row"><span>'+x+'</span><input type="checkbox"></div>').join("")+'</div>')+'</div>';}}
]});})();